문 10. 다음 C 프로그램의 출력 결과로 옳은 것은?
#include<stdio.h>
void func(int *a, int b, int *c)
{
int x;
x = *a;
*a = x++;
x = b;
b = ++x;
--(*c);
}
int main()
{
int a, b, c[1];
a = 20;
b = 20;
c[0] = 20;
func(&a, b, c);
printf("a = %d b = %d c = %d\n", a, b, *c);
return 0;
}

